from jinja2 import Environment, nodes, Markup, TemplateSyntaxError, TemplateAssertionError, mark_safe
from jinja2.ext import Extension

class ConditionalI18nExtension(Extension):
    tags = {'ctrans'

    def __init__(self, environment):
        super().__init__(environment)

    def parse(self, parser):
        condition = parser.parse_expression()
        variables = {}
        trimmed = False
        if parser.stream.current.value == 'trimmed':
            trimmed = True
            parser.stream.next()
        if parser.stream.current.value == ',':
            parser.stream.next()
        while parser.stream.current.value != 'endctrans':
            key = parser.stream.current.value
            parser.stream.next()
            if parser.stream.current.value == '=':
                parser.stream.next()
                value = parser.parse_expression()
                variables[key] = value
            else:
                variables[key] = None
            if parser.stream.current.value == 'trimmed':
                trimmed = True
                parser.stream.next()
            if parser.stream.current.value == ',':
                parser.stream.next()
        fallback_block = parser.parse_block(nodes.Output)
        return self._make_conditional_node(condition, variables, fallback_block, trimmed)

    def _make_conditional_node(self, condition, variables, fallback_block, trimmed):
        if environment.newstyle_gettext:
            def gettext(message, **kwargs):
                return message % kwargs
        else:
            def gettext(message, **kwargs):
                return message % kwargs
        if environment.newstyle_gettext:
            def ngettext(singular, plural, count, **kwargs):
                return singular if count == 1 else plural % kwargs
        else:
            def ngettext(singular, plural, count, **kwargs):
                return singular if count == 1 else plural % kwargs
        if environment.policies.get('ext.i18n.trimmed', False):
            def trim_whitespace(node):
                return Markup(node).strip()
        else:
            def trim_whitespace(node):
                return Markup(node)
        if condition.test(parser):
            if 'count' in variables:
                return ngettext(gettext(fallback_block), variables['count'])
            else:
                return gettext(fallback_block)
        else:
            if 'count' in variables:
                return ngettext(variables['count'], fallback_block, variables['count'])
            else:
                return fallback_block
